  const s80Text=__SMART_BILLING_TEXTS__;
  Object.assign(state,{s80Silence:1500,s80Scroll:0});
  function s80Guides(){const t=s80Text;return [
    {title:t.smartBillingImageBilling,icon:'images',desc:t.smartBillingImageBillingDesc,body:t.smartBillingImageBillingGuide,requirement:t.smartBillingVisionAIRequired,hint:t.smartBillingGuideHint},
    {title:t.smartBillingCameraBilling,icon:'camera',desc:t.smartBillingCameraBillingDesc,body:t.smartBillingCameraBillingGuide,requirement:t.smartBillingVisionAIRequired,hint:t.smartBillingGuideHint},
    {title:t.smartBillingVoiceBilling,icon:'mic',desc:t.smartBillingVoiceBillingDesc,body:t.smartBillingVoiceBillingGuide,requirement:t.smartBillingAIRequired,hint:t.smartBillingGuideHint},
    {title:t.shareBilling,icon:'share-2',desc:t.shareBillingDesc,body:t.shareBillingGuide,requirement:t.smartBillingVisionAIRequired,hint:t.shareBillingActionHint}];}
  function s80GuideBody(selected){const g=selected||s80Guides().find(g=>g.title===state.nFeature)||s80Guides()[0];return `<div class="s80-guide"><p class="s80-copy">${esc(g.body)}</p><div class="s80-requirement">${icon('info')}<span>${esc(g.requirement)}</span></div><div class="s80-action-hint">${icon('hand')}<span>${esc(g.hint)}</span></div></div>${fCTA('r-close',s80Text.commonKnow)}`;}
  function s80VoiceBody(){const t=s80Text;return `<div class="n-options">${[['auto',t.voiceTriggerModeAuto,t.voiceTriggerModeAutoDesc],['hold',t.voiceTriggerModeHold,t.voiceTriggerModeHoldDesc]].map(([v,title,desc])=>btn('n-voice:'+v,`<span><b>${esc(title)}</b><small>${esc(desc)}</small></span>${state.nVoice===v?icon('check'):''}`,title,'n-option')).join('')}</div>${fCTA('r-close',t.commonCancel)}`;}
  fDefs['feature-guide'].body=s80GuideBody;fDefs['voice-trigger'].body=s80VoiceBody;
  const s80GuideRoutes=Object.fromEntries(['image','camera','voice','share'].map((key,i)=>['smart-guide-'+key,s80Guides()[i]]));
  for(const[key,g]of Object.entries(s80GuideRoutes)){rSpecs[key]={title:g.title,host:'smart',kind:'dialog'};fDefine(key,g.title+' · 原使用说明','自动化与识别','settings/smart_billing_page.dart',()=>s80GuideBody(g));}
  const s80Modal=rModalBody;rModalBody=function(key){return s80GuideRoutes[key]?s80GuideBody(s80GuideRoutes[key]):s80Modal(key);};

  const s80Open=rOpenModal;rOpenModal=function(key){if(key==='feature-guide')rSpecs[key].title=(s80Guides().find(g=>g.title===state.nFeature)||s80Guides()[0]).title;if(key==='voice-trigger')rSpecs[key].title=s80Text.smartBillingVoiceTrigger;return s80Open(key);};
  function s80Toggle(key,name,title,description,value){return btn('s80-toggle:'+key,`<span class="bc-menu-symbol">${icon(name)}</span><span class="bc-menu-copy"><b>${esc(title)}</b><small>${esc(description)}</small></span><span class="bc-switch" aria-hidden="true"></span>`,title,'bc-menu-row',`role="switch" aria-checked="${fVal(key,value)}"`);}
  smart=function(){const t=s80Text,g=s80Guides(),android=state.nPlatform==='android',gp=state.nChannel==='googlePlay',guide=g=>menuRow('n-guide:'+g.title,g.icon,g.title,g.desc);return `<div class="s80-shell">${subhead(t.smartBillingPageTitle)}<div class="s80-scroll"><p class="bc-small s80-subtitle">${esc(t.smartBillingPageSubtitle)}</p>${menuCard([['f-go:ai-settings','sparkles',t.aiSettingsTitle,t.aiSettingsSubtitle]])}${surface(g.slice(0,3).map(guide).join(''),'s80-card')}${surface((android?guide(g[3]):'')+(!(android&&gp)?menuRow('f-go:auto-billing','scan-line',android?t.autoScreenshotBilling:t.autoScreenshotBillingIosTitle,android?t.autoScreenshotBillingDesc:t.autoScreenshotBillingIosDesc):'')+menuRow('f-go:shortcuts','command',t.shortcutsGuide,t.shortcutsGuideDesc),'s80-card')}${surface(s80Toggle('s80AutoTags','tags',t.smartBillingAutoTags,t.smartBillingAutoTagsDesc,true)+s80Toggle('s80AutoAttachment','paperclip',t.smartBillingAutoAttachment,t.smartBillingAutoAttachmentDesc,true)+s80Toggle('s80KeepOriginal','image',t.attachmentKeepOriginal,t.attachmentKeepOriginalDesc,false),'s80-card')}${surface(menuRow('r-open:voice-trigger','mic',t.smartBillingVoiceTrigger,state.nVoice==='auto'?t.voiceTriggerModeAuto:t.voiceTriggerModeHold)+(state.nVoice==='auto'?`<label class="s80-slider"><span>${esc(t.smartBillingVoiceSilenceTimeout)}</span><output>${esc(t.smartBillingVoiceSilenceTimeoutValue.replace('{seconds}',(state.s80Silence/1000).toFixed(1)))}</output><input data-n-silence type="range" min="500" max="4000" step="100" value="${state.s80Silence}" aria-label="${esc(t.smartBillingVoiceSilenceTimeout)}"></label>`:''),'s80-card')}</div></div>`;};
  for(const[key,title,platform,channel]of [['smart-direct','智能记账 · Android直装','android','direct'],['smart-gp','智能记账 · Google Play','android','googlePlay'],['smart-ios','智能记账 · iOS','ios','direct']]){fDefine(key,title,'自动化与识别','settings/smart_billing_page.dart',smart);}
  const s80Render=fRender;fRender=function(key){const p={'smart-direct':['android','direct'],'smart-gp':['android','googlePlay'],'smart-ios':['ios','direct']}[key];if(p){state.nPlatform=p[0];state.nChannel=p[1];return smart();}return s80Render(key);};
  const s80Remember=zRememberCategoryScroll;zRememberCategoryScroll=function(){s80Remember();const scroll=phone.querySelector('.s80-scroll');if(scroll)state.s80Scroll=scroll.scrollTop;};
  const s80After=rAfterRender;rAfterRender=function(){s80After();const scroll=phone.querySelector('.s80-scroll');if(scroll)scroll.scrollTop=state.s80Scroll||0;};
  root.addEventListener('change',e=>{if(e.target.matches('[data-n-silence]')){state.s80Silence=Math.min(4000,Math.max(500,Math.round(Number(e.target.value)/100)*100));render();}},true);

  root.addEventListener('input',e=>{if(e.target.matches('[data-n-silence]'))e.target.closest('label').querySelector('output').textContent=s80Text.smartBillingVoiceSilenceTimeoutValue.replace('{seconds}',(Number(e.target.value)/1000).toFixed(1));});

  root.addEventListener('click',e=>{const target=e.target.closest('[data-action^="s80-toggle:"]');if(!target)return;const key=target.dataset.action.slice(11);state.fForm[key]=target.getAttribute('aria-checked')!=='true';render();persist();});
